/* ─────────────── Satsuma tokens: reels, in segments ─────────────── */
@theme static {
  --color-paper: #FFF6EA;     /* the page */
  --color-ink: #1F1520;       /* text */
  --color-aubergine: #3A1D4A; /* the primary action, the dark bands */
  --color-satsuma: #FF7A2F;   /* the one accent: fills, rings, never small text */
  --color-apricot: #FFD9B0;   /* tints, card ground */
  --color-leaf: #2F5D3A;      /* rare: the leaf, one green note */

  --font-sa-display: var(--font-bricolage), ui-sans-serif, system-ui, sans-serif;
  --font-sa-body: var(--font-inter-body), ui-sans-serif, system-ui, sans-serif;

  /* motion: glide + settle */
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --ease-spring: linear(0, 0.4 9%, 0.86 22%, 1.04 33%, 1.01 46%, 0.995 62%, 1);
  --dur-instant: 90ms;
  --dur-fast: 180ms;
  --dur-base: 420ms;
  --dur-slow: 850ms;
  --dur-hero: 1100ms;
  --reveal-shift: 28px;
  --stagger: 80ms;
}

/* ─────────────── Base ─────────────── */
.sa-body {
  /* One frame unit. The hero is a 1440×1080 picture scaled to fit the screen. */
  --u: min(calc(100vw / 1440), calc(100svh / 1080));
  --sa-gutter: clamp(20px, 5vw, 72px);
  --sa-muted: color-mix(in srgb, var(--color-ink) 68%, var(--color-paper));
  --sa-hair: color-mix(in srgb, var(--color-ink) 14%, transparent);
  --sa-card: color-mix(in srgb, var(--color-paper) 55%, white);
  --sa-tint: color-mix(in srgb, var(--color-apricot) 38%, var(--color-paper));

  margin: 0;
  background-color: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-sa-body);
  font-size: 1.0625rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

@media (max-width: 820px) {
  .sa-body {
    --u: calc(100vw / 640);
  }
}

html:has(.sa-body) {
  scroll-padding-top: 88px;
  background-color: var(--color-paper);
}

html.sa-locked {
  overflow: hidden;
}

.sa-body *,
.sa-body *::before,
.sa-body *::after {
  box-sizing: border-box;
}

.sa-body main,
.sa-body footer {
  overflow-x: clip;
}

.sa-body ::selection {
  background: var(--color-satsuma);
  color: var(--color-ink);
}

.sa-body :focus-visible {
  outline: 2px solid var(--color-aubergine);
  outline-offset: 3px;
}

.sa-brief :focus-visible,
.sa-band :focus-visible,
.sa-footer :focus-visible,
.sa-pack[data-popular="true"] :focus-visible,
.sa-menu :focus-visible {
  outline-color: var(--color-satsuma);
}

:where(.sa-body) img,
:where(.sa-body) svg {
  display: block;
  max-width: 100%;
}

:where(.sa-body) :where(h1, h2, h3, p, dl, dd, ol, ul, figure, fieldset, legend) {
  margin: 0;
  padding: 0;
}

:where(.sa-body) :where(ol, ul) {
  list-style: none;
}

:where(.sa-body) :where(fieldset) {
  border: 0;
  min-width: 0;
}

:where(.sa-body) :where(button, input, select, textarea) {
  font: inherit;
  color: inherit;
}

.sa-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.sa-skip {
  position: fixed;
  left: 16px;
  top: 12px;
  z-index: 100;
  padding: 10px 14px;
  background: var(--color-aubergine);
  color: var(--color-paper);
  font: 500 14px/1 var(--font-sa-body);
  border-radius: 999px;
  transform: translateY(-160%);
  transition: transform var(--dur-fast) var(--ease-out);
}

.sa-skip:focus-visible {
  transform: none;
}

.sa-tabular {
  font-variant-numeric: tabular-nums;
}

.sa-wrap {
  width: min(100% - 2 * var(--sa-gutter), 1240px);
  margin-inline: auto;
}

/* ─────────────── Buttons ─────────────── */
.sa-btn {
  --fill: var(--color-satsuma);
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 46px;
  padding-inline: 24px;
  border: 0;
  border-radius: 999px;
  overflow: hidden;
  font: 500 15.5px/1 var(--font-sa-body);
  letter-spacing: -0.005em;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition:
    transform var(--dur-instant) var(--ease-out),
    color var(--dur-fast) var(--ease-out);
}

.sa-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background: var(--fill);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--dur-base) var(--ease-out);
}

.sa-btn--aub {
  background: var(--color-aubergine);
  color: var(--color-paper);
}

.sa-btn--sat {
  --fill: var(--color-aubergine);
  background: var(--color-satsuma);
  color: var(--color-ink);
}

.sa-btn--paper {
  --fill: var(--color-apricot);
  background: color-mix(in srgb, var(--color-paper) 40%, white);
  color: var(--color-ink);
  box-shadow: inset 0 0 0 1px var(--sa-hair);
}

.sa-btn:active {
  transform: scale(0.97);
  transition-duration: var(--dur-instant);
}

.sa-btn[disabled] {
  cursor: progress;
}

.sa-btn__roll {
  display: inline-grid;
  overflow: clip;
}

.sa-btn__roll > span {
  grid-area: 1 / 1;
  transition: transform var(--dur-base) var(--ease-out);
}

.sa-btn__roll > span + span {
  transform: translateY(110%);
}

@media (hover: hover) and (pointer: fine) {
  .sa-btn:hover::before {
    transform: scaleX(1);
  }
  .sa-btn--aub:hover,
  .sa-btn--paper:hover {
    color: var(--color-ink);
  }
  .sa-btn--sat:hover {
    color: var(--color-paper);
  }
  .sa-btn:hover .sa-btn__roll > span:first-child {
    transform: translateY(-110%);
  }
  .sa-btn:hover .sa-btn__roll > span + span {
    transform: none;
  }
}

.sa-magnetic {
  display: inline-block;
  transform: translate3d(var(--mx, 0px), var(--my, 0px), 0);
}

.sa-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 500;
  color: var(--color-aubergine);
  text-decoration: none;
  background: linear-gradient(currentColor, currentColor) left bottom / 0% 1.5px no-repeat;
  padding-bottom: 3px;
  transition: background-size var(--dur-base) var(--ease-out);
}

.sa-link__arrow {
  transition: transform var(--dur-base) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .sa-link:hover {
    background-size: 100% 1.5px;
  }
  .sa-link:hover .sa-link__arrow {
    transform: translateX(5px);
  }
}

/* ─────────────── Brand ─────────────── */
.sa-logo {
  display: inline-flex;
  align-items: center;
  gap: 0.4em;
  color: var(--color-aubergine);
  font: 700 max(calc(26 * var(--u)), 20px) / 1 var(--font-sa-display);
  letter-spacing: -0.03em;
}

.sa-logo__mark {
  width: 1.35em;
  height: 1.35em;
  --sa-fruit: var(--color-satsuma);
}

.sa-mark__fruit {
  fill: var(--sa-fruit, var(--color-satsuma));
}

.sa-mark__leaf {
  fill: var(--color-leaf);
}

.sa-logo__dot {
  color: var(--color-satsuma);
}

/* ─────────────── Header ─────────────── */
.sa-header {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 50;
  transition: transform var(--dur-base) var(--ease-out);
}

.sa-header::before {
  content: "";
  position: absolute;
  inset: 0;
  background: color-mix(in srgb, var(--color-paper) 88%, transparent);
  backdrop-filter: blur(14px);
  opacity: 0;
  transform: translateY(-100%);
  transition:
    opacity var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
}

.sa-header[data-state="compact"]::before,
.sa-header[data-state="hidden"]::before {
  opacity: 1;
  transform: none;
}

.sa-header[data-state="hidden"] {
  transform: translateY(-110%);
}

.sa-header__bar {
  position: relative;
  width: calc(1440 * var(--u));
  height: max(calc(98 * var(--u)), 62px);
  margin-inline: auto;
}

.sa-header__logo {
  position: absolute;
  left: calc(37 * var(--u));
  top: calc(36 * var(--u));
  text-decoration: none;
}

.sa-nav {
  position: absolute;
  left: calc(505 * var(--u));
  top: calc(29 * var(--u));
  height: max(calc(40 * var(--u)), 34px);
  display: flex;
  align-items: center;
}

.sa-nav ul {
  display: flex;
  gap: calc(31 * var(--u));
}

.sa-nav a {
  display: block;
  padding-block: 8px;
  font: 400 max(calc(16.4 * var(--u)), 13px) / 1 var(--font-sa-body);
  color: var(--color-ink);
  text-decoration: none;
  white-space: nowrap;
}

.sa-nav__indicator {
  position: absolute;
  left: 0;
  bottom: -2px;
  width: 100px;
  height: 3px;
  border-radius: 3px;
  background: var(--color-satsuma);
  transform: translateX(var(--x, 0px)) scaleX(var(--w, 0));
  transform-origin: left;
  opacity: 0;
  transition:
    transform var(--dur-base) var(--ease-out),
    opacity var(--dur-fast) var(--ease-out);
}

.sa-nav__indicator[data-on="true"] {
  opacity: 1;
}

.sa-header__login,
.sa-header__signup {
  position: absolute;
  top: calc(29 * var(--u));
  height: max(calc(40 * var(--u)), 34px);
  padding-inline: 0;
  font-size: max(calc(15.4 * var(--u)), 13px);
}

.sa-header__login {
  left: calc(1211 * var(--u));
  width: max(calc(92 * var(--u)), 74px);
}

.sa-header__signup {
  left: calc(1304 * var(--u));
  width: max(calc(97 * var(--u)), 80px);
}

.sa-header__rail {
  position: absolute;
  inset: auto 0 0 0;
  height: 2px;
  background: var(--sa-hair);
  opacity: 0;
  transition: opacity var(--dur-base) var(--ease-out);
}

.sa-header[data-state="compact"] .sa-header__rail,
.sa-header[data-state="hidden"] .sa-header__rail {
  opacity: 1;
}

.sa-header__rail-fill {
  position: absolute;
  inset: 0;
  background: var(--color-satsuma);
  transform-origin: left;
  transform: scaleX(var(--sa-page, 0));
}

.sa-menu-toggle {
  display: none;
  position: relative;
  width: 44px;
  height: 44px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  cursor: pointer;
}

.sa-menu-toggle span {
  position: absolute;
  left: 11px;
  right: 11px;
  top: 50%;
  height: 2px;
  margin-top: -1px;
  border-radius: 2px;
  background: var(--color-aubergine);
  transition: transform var(--dur-base) var(--ease-out);
}

.sa-menu-toggle span:first-child {
  transform: translateY(-4px);
}

.sa-menu-toggle span:last-child {
  transform: translateY(4px);
}

.sa-menu-toggle[aria-expanded="true"] span {
  background: var(--color-paper);
}

.sa-menu-toggle[aria-expanded="true"] span:first-child {
  transform: rotate(45deg);
}

.sa-menu-toggle[aria-expanded="true"] span:last-child {
  transform: rotate(-45deg);
}

.sa-menu-toggle:active {
  transform: scale(0.92);
}

.sa-menu {
  display: none;
}

@media (max-width: 820px) {
  .sa-header__bar {
    width: 100%;
    height: 64px;
    padding-inline: 20px;
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .sa-header__logo {
    position: static;
    margin-right: auto;
  }
  .sa-logo {
    font-size: 22px;
  }
  .sa-nav,
  .sa-header__login {
    display: none;
  }
  .sa-header__signup {
    position: static;
    width: auto;
    height: 40px;
    padding-inline: 20px;
    font-size: 14px;
  }
  .sa-menu-toggle {
    display: block;
    margin-right: -10px;
  }
  .sa-menu {
    position: fixed;
    inset: 0;
    z-index: 45;
    display: grid;
    align-content: center;
    padding: 96px 28px 40px;
    background: var(--color-aubergine);
    color: var(--color-paper);
    clip-path: circle(0% at calc(100% - 38px) 32px);
    visibility: hidden;
    transition:
      clip-path var(--dur-base) var(--ease-in-out),
      visibility 0s linear var(--dur-base);
  }
  .sa-menu[data-open="true"] {
    clip-path: circle(150% at calc(100% - 38px) 32px);
    visibility: visible;
    transition:
      clip-path var(--dur-base) var(--ease-in-out),
      visibility 0s;
  }
  .sa-menu ol {
    display: grid;
    gap: 6px;
    margin-bottom: 32px;
  }
  .sa-menu ol a {
    display: flex;
    align-items: baseline;
    gap: 14px;
    font: 700 clamp(34px, 10vw, 54px) / 1.15 var(--font-sa-display);
    letter-spacing: -0.03em;
    color: inherit;
    text-decoration: none;
  }
  .sa-menu__num {
    font: 500 13px/1 var(--font-sa-body);
    color: var(--color-apricot);
  }
  .sa-menu li {
    opacity: 0;
    transform: translateY(18px);
    transition:
      opacity var(--dur-base) var(--ease-out),
      transform var(--dur-base) var(--ease-out);
  }
  .sa-menu[data-open="true"] li {
    opacity: 1;
    transform: none;
    transition-delay: calc(140ms + var(--i, 0) * 50ms);
  }
  .sa-menu__cta {
    justify-self: start;
  }
}

/* ─────────────── Hero: the 1440×1080 frame ─────────────── */
.sa-hero {
  position: relative;
  height: calc(1080 * var(--u));
  overflow-x: clip;
  --sa-out: 0;
}

.sa-hero__frame {
  position: relative;
  width: calc(1440 * var(--u));
  height: 100%;
  margin-inline: auto;
  transform-origin: 50% 45%;
  transform: scale(calc(1 - var(--sa-out) * 0.05));
  opacity: calc(1 - var(--sa-out) * 0.55);
}

html[data-sa-motion="live"] .sa-hero {
  position: sticky;
  top: 0;
}

.sa-h1 {
  position: absolute;
  inset: calc(176 * var(--u)) 0 auto 0;
  z-index: 2;
  text-align: center;
  font: 700 calc(88 * var(--u)) / calc(92 * var(--u)) var(--font-sa-display);
  letter-spacing: -0.035em;
  color: var(--color-ink);
}

.sa-h1__line {
  display: block;
  overflow: clip;
  padding-bottom: 0.14em;
  margin-bottom: -0.14em;
}

.sa-h1__line--2 {
  letter-spacing: -0.022em;
}

.sa-h1__text {
  display: block;
}

.sa-sub {
  position: absolute;
  left: 50%;
  translate: -50% 0;
  top: calc(394 * var(--u));
  z-index: 2;
  width: max-content;
  max-width: 100%;
  text-align: center;
  font: 400 max(calc(20.8 * var(--u)), 14px) / calc(32 * var(--u)) var(--font-sa-body);
  color: var(--sa-muted);
}

.sa-sub span {
  display: block;
}

/* Hero marks: a turning seal, a leaf sprig on a wedge, and a trust line */
.sa-seal {
  position: absolute;
  left: calc(1196 * var(--u));
  top: calc(292 * var(--u));
  z-index: 3;
  display: grid;
  place-items: center;
  width: max(calc(150 * var(--u)), 96px);
  aspect-ratio: 1;
  pointer-events: none;
}

.sa-seal > svg:not(.sa-seal__mark) {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.sa-seal__disc {
  fill: var(--color-apricot);
}

.sa-seal__ring {
  transform-box: view-box;
  transform-origin: 80px 80px;
}

.sa-seal__text {
  font: 600 10.6px / 1 var(--font-sa-body);
  fill: var(--color-aubergine);
}

.sa-seal__mark {
  position: relative;
  width: 44%;
  height: 44%;
  color: var(--color-aubergine);
  --sa-fruit: var(--color-satsuma);
}

.sa-sprig {
  position: absolute;
  left: calc(206 * var(--u));
  top: calc(344 * var(--u));
  z-index: 3;
  width: max(calc(116 * var(--u)), 72px);
  overflow: visible;
  pointer-events: none;
}

.sa-sprig__stem {
  fill: none;
  stroke: var(--color-leaf);
  stroke-width: 3.4;
  stroke-linecap: round;
}

.sa-sprig__leaf {
  fill: var(--color-leaf);
  transform-box: fill-box;
  transform-origin: 50% 100%;
}

.sa-sprig__wedge {
  fill: var(--color-satsuma);
}

.sa-sprig__veins {
  fill: none;
  stroke: var(--color-paper);
  stroke-width: 2.2;
  stroke-linecap: round;
  opacity: 0.7;
}

.sa-trust {
  position: absolute;
  left: 50%;
  translate: -50% 0;
  top: calc(994 * var(--u));
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 0.6em;
  width: max-content;
  max-width: 100%;
  white-space: nowrap;
  font: 500 max(calc(14.5 * var(--u)), 13px) / 1.2 var(--font-sa-body);
  color: var(--sa-muted);
}

.sa-trust__dot {
  flex: none;
  width: 0.7em;
  height: 0.7em;
  border-radius: 50% 50% 50% 0;
  background: var(--color-satsuma);
  rotate: -45deg;
}

.sa-draw {
  stroke-dasharray: 1;
  stroke-dashoffset: 0;
}

/* CTA: an aubergine pill sitting on a satsuma plate; on hover or press it settles down onto it */
.sa-cta {
  position: absolute;
  z-index: 3;
  left: calc(626 * var(--u));
  top: calc(901 * var(--u));
  width: max(calc(190 * var(--u)), 156px);
  height: max(calc(74 * var(--u)), 62px);
  display: grid;
  place-items: center;
}

.sa-cta__plate {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: var(--color-satsuma);
}

.sa-cta__magnet {
  display: block;
  translate: calc(-7 * var(--u)) calc(-7 * var(--u));
}

.sa-cta:active .sa-cta__magnet {
  translate: 0 0;
}

@media (hover: hover) and (pointer: fine) {
  .sa-cta:hover .sa-cta__magnet,
  .sa-cta:focus-within .sa-cta__magnet {
    translate: 0 0;
  }
}

.sa-btn--hero {
  width: calc(172 * var(--u));
  height: calc(58 * var(--u));
  min-width: 136px;
  min-height: 48px;
  padding-inline: 0;
  font-size: max(calc(18 * var(--u)), 15px);
}

/* ─────────────── The reel wheel ─────────────── */
.sa-wheel {
  --wu: var(--u);
  position: absolute;
  left: 50%;
  top: 0;
  z-index: 1;
  width: 100vw;
  height: 100%;
  margin-left: -50vw;
  cursor: grab;
  touch-action: pan-y;
  user-select: none;
  -webkit-user-select: none;
  outline-offset: -4px;
}

.sa-wheel[data-dragging="true"] {
  cursor: grabbing;
}

.sa-wheel__probe {
  position: absolute;
  left: 0;
  top: 0;
  width: calc(1000 * var(--wu));
  height: 1px;
  visibility: hidden;
  pointer-events: none;
}

.sa-wheel__track {
  position: absolute;
  inset: 0;
  contain: layout style;
}

.sa-card {
  position: absolute;
  contain: layout style paint;
  overflow: hidden;
  background: var(--color-apricot);
  will-change: transform, clip-path;
  -webkit-tap-highlight-color: transparent;
}

.sa-card__media {
  position: absolute;
  inset: 0;
}

.sa-scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  transition: scale var(--dur-slow) var(--ease-out);
}

.sa-card__video {
  position: absolute;
  left: 0;
  top: 0;
  max-width: none;
  object-fit: fill;
  opacity: 0;
  transition: opacity var(--dur-slow) var(--ease-out);
}

.sa-card__video[data-ready="true"] {
  opacity: 1;
}

.sa-card__play {
  position: absolute;
  left: calc(14 * var(--wu));
  bottom: calc(14 * var(--wu));
  width: calc(34 * var(--wu));
  height: calc(34 * var(--wu));
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--color-paper) 42%, transparent);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  transition:
    scale var(--dur-base) var(--ease-spring),
    background-color var(--dur-fast) var(--ease-out);
}

.sa-card__play svg {
  width: 62%;
  height: 62%;
  fill: var(--color-paper);
}

@media (hover: hover) and (pointer: fine) {
  .sa-card:hover .sa-card__play {
    scale: 1.14;
    background: var(--color-satsuma);
  }
  .sa-card:hover .sa-scene {
    scale: 1.06;
  }
}

/* Scene loops: transform-only, paused off-screen */
.sa-f-paper { fill: var(--color-paper); }
.sa-f-ink { fill: var(--color-ink); }
.sa-f-aub { fill: var(--color-aubergine); }
.sa-f-sat { fill: var(--color-satsuma); }
.sa-f-apr { fill: var(--color-apricot); }
.sa-f-leaf { fill: var(--color-leaf); }
.sa-f-apr-soft { fill: color-mix(in srgb, var(--color-apricot) 45%, var(--color-paper)); }
.sa-f-leaf-soft { fill: color-mix(in srgb, var(--color-leaf) 22%, var(--color-paper)); }
.sa-s-paper,
.sa-s-ink,
.sa-s-aub,
.sa-s-sat,
.sa-s-apr,
.sa-s-leaf {
  fill: none;
  stroke-width: 6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.sa-s-paper { stroke: var(--color-paper); }
.sa-s-ink { stroke: var(--color-ink); }
.sa-s-aub { stroke: var(--color-aubergine); }
.sa-s-sat { stroke: var(--color-satsuma); }
.sa-s-apr { stroke: var(--color-apricot); }
.sa-s-leaf { stroke: var(--color-leaf); }
.sa-sw-8 { stroke-width: 8; }
.sa-sw-10 { stroke-width: 10; }
.sa-sw-14 { stroke-width: 14; }
.sa-sw-18 { stroke-width: 18; }
.sa-sw-20 { stroke-width: 20; }
.sa-o-3 { opacity: 0.3; }
.sa-o-6 { opacity: 0.6; }

.sa-a {
  transform-box: fill-box;
  transform-origin: center;
}

.sa-a-sway,
.sa-a-vb {
  transform-box: view-box;
}

.sa-wheel[data-playing="false"] .sa-a {
  animation-play-state: paused !important;
}

/* ─────────────── Type and reveals ─────────────── */
.sa-h2 {
  margin-top: 18px;
  font: 700 clamp(2.4rem, 5.2vw, 4.6rem) / 1 var(--font-sa-display);
  letter-spacing: -0.035em;
  color: var(--color-ink);
}

.sa-h2 em {
  font-style: normal;
  background: linear-gradient(transparent 62%, var(--color-satsuma) 62% 92%, transparent 92%);
  padding-inline: 0.06em;
  margin-inline: -0.06em;
}

.sa-mask {
  display: block;
  overflow: clip;
  padding-bottom: 0.14em;
  margin-bottom: -0.14em;
}

.sa-lede {
  max-width: 54ch;
  margin-top: 22px;
  font-size: 1.125rem;
  color: var(--sa-muted);
}

.sa-eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  font: 500 0.8125rem/1 var(--font-sa-body);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-aubergine);
}

.sa-eyebrow__rule {
  width: 34px;
  height: 2px;
  border-radius: 2px;
  background: var(--color-satsuma);
  transform-origin: left;
}

.sa-eyebrow__n {
  font-variant-numeric: tabular-nums;
  color: var(--sa-muted);
}

/* ─────────────── Sheet: the bands that slide over the hero ─────────────── */
.sa-sheet {
  position: relative;
  z-index: 1;
  background: var(--color-paper);
  border-radius: clamp(24px, 3.2vw, 48px) clamp(24px, 3.2vw, 48px) 0 0;
}

.sa-band {
  background: var(--color-aubergine);
  color: var(--color-paper);
  border-radius: inherit;
  overflow: hidden;
}

.sa-marquee {
  overflow: hidden;
  padding-block: clamp(18px, 2.4vw, 30px);
}

.sa-marquee__track {
  display: flex;
  width: max-content;
}

.sa-marquee__run {
  display: flex;
}

.sa-marquee__item {
  display: inline-flex;
  align-items: center;
  font: 700 clamp(2rem, 4.6vw, 4rem) / 1 var(--font-sa-display);
  letter-spacing: -0.03em;
  white-space: nowrap;
}

.sa-marquee__sep {
  padding-inline: 0.5em;
  color: var(--color-satsuma);
}

.sa-how,
.sa-makers,
.sa-packs,
.sa-brief {
  padding-block: clamp(72px, 10vw, 140px);
}

.sa-how {
  background: var(--color-paper);
}

/* How it works */
.sa-steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(20px, 3vw, 44px);
  margin-top: clamp(40px, 6vw, 72px);
}

.sa-step {
  position: relative;
  display: grid;
  align-content: start;
  gap: 10px;
  padding: 28px 26px 26px;
  border-radius: 28px;
  background: var(--sa-tint);
}

.sa-step__n {
  font: 800 clamp(3.4rem, 6vw, 5.2rem) / 0.9 var(--font-sa-display);
  letter-spacing: -0.04em;
  color: var(--color-satsuma);
}

.sa-step__title {
  font: 700 1.6rem / 1.1 var(--font-sa-display);
  letter-spacing: -0.025em;
}

.sa-step__body {
  color: var(--sa-muted);
}

.sa-step__figure {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 14px;
  padding-top: 16px;
  border-top: 1.5px dashed color-mix(in srgb, var(--color-aubergine) 40%, transparent);
}

.sa-step__num {
  font: 800 2.6rem / 1 var(--font-sa-display);
  letter-spacing: -0.04em;
  color: var(--color-aubergine);
}

.sa-step__unit {
  font-weight: 600;
  color: var(--color-aubergine);
}

.sa-step__label {
  margin-left: auto;
  font-size: 0.875rem;
  color: var(--sa-muted);
}

.sa-step__link {
  position: absolute;
  right: -62px;
  top: 38px;
  z-index: 2;
  width: 80px;
  fill: none;
  stroke: var(--color-aubergine);
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Makers */
.sa-makers {
  background: var(--sa-tint);
}

.sa-makers__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(18px, 2.4vw, 32px);
  margin-top: clamp(40px, 6vw, 64px);
}

.sa-tilt {
  transform-style: preserve-3d;
  transform: perspective(900px) translateY(var(--lift, 0px)) rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg));
  transition: transform var(--dur-base) var(--ease-out);
}

.sa-tilt:active {
  --lift: -2px;
}

.sa-makers__grid > li {
  display: flex;
}

.sa-maker {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  overflow: hidden;
  border-radius: 28px;
  background: var(--sa-card);
  box-shadow: inset 0 0 0 1px var(--sa-hair);
}

.sa-maker::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(420px circle at var(--sx, 50%) var(--sy, 0%), color-mix(in srgb, var(--color-satsuma) 22%, transparent), transparent 60%);
  opacity: 0;
  transition: opacity var(--dur-base) var(--ease-out);
  pointer-events: none;
}

.sa-maker__media {
  position: relative;
  aspect-ratio: 4 / 3.4;
  overflow: hidden;
}

.sa-maker__media > svg,
.sa-maker__media > picture,
.sa-maker__media > picture img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: scale var(--dur-slow) var(--ease-out);
}

.sa-maker__rate {
  position: absolute;
  left: 14px;
  bottom: 14px;
  padding: 7px 12px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--color-paper) 85%, transparent);
  font: 500 0.8125rem/1 var(--font-sa-body);
  color: var(--color-ink);
}

.sa-maker__body {
  display: grid;
  flex: 1;
  grid-template-rows: auto auto 1fr auto auto;
  gap: 6px;
  padding: 20px 22px 24px;
}

.sa-maker__name {
  font: 700 1.5rem / 1.1 var(--font-sa-display);
  letter-spacing: -0.025em;
}

.sa-maker__craft {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-aubergine);
}

.sa-maker__line {
  color: var(--sa-muted);
}

.sa-maker__stats {
  display: grid;
  grid-template-columns: repeat(3, auto);
  justify-content: space-between;
  margin-block: 10px 12px;
  padding-block: 12px;
  border-block: 1.5px dashed var(--sa-hair);
}

.sa-maker__stats dt {
  font-size: 0.75rem;
  color: var(--sa-muted);
}

.sa-maker__stats dd {
  font: 700 1.1rem / 1.2 var(--font-sa-display);
  font-variant-numeric: tabular-nums;
}

.sa-maker .sa-link {
  justify-self: start;
}

@media (hover: hover) and (pointer: fine) {
  .sa-tilt:hover {
    --lift: -6px;
  }
  .sa-maker:hover::after {
    opacity: 1;
  }
  .sa-maker:hover .sa-maker__media > svg,
  .sa-maker:hover .sa-maker__media > picture {
    scale: 1.06;
  }
  .sa-makers__grid:has(.sa-maker:hover) li:not(:has(.sa-maker:hover)) {
    opacity: 0.62;
  }
}

.sa-makers__grid li {
  transition: opacity var(--dur-base) var(--ease-out);
}

/* Packs */
.sa-packs__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(18px, 2.4vw, 32px);
  margin-top: clamp(40px, 6vw, 64px);
  align-items: stretch;
}

.sa-packs__grid > li {
  display: flex;
}

.sa-pack {
  position: relative;
  display: grid;
  align-content: start;
  gap: 12px;
  width: 100%;
  padding: 28px 28px 30px;
  border-radius: 32px;
  background: var(--sa-card);
  box-shadow: inset 0 0 0 1px var(--sa-hair);
  transition: transform var(--dur-base) var(--ease-out);
}

.sa-pack[data-popular="true"] {
  background: var(--color-aubergine);
  color: var(--color-paper);
  box-shadow: none;
}

.sa-pack__flag {
  position: absolute;
  right: 22px;
  top: 22px;
  padding: 7px 12px;
  border-radius: 999px;
  background: var(--color-satsuma);
  color: var(--color-ink);
  font: 600 0.75rem/1 var(--font-sa-body);
  letter-spacing: 0.04em;
}

.sa-pack__ring {
  width: 112px;
  height: 112px;
  margin-bottom: 6px;
}

.sa-ring__peel {
  fill: color-mix(in srgb, var(--color-apricot) 55%, var(--color-paper));
}

.sa-pack[data-popular="true"] .sa-ring__peel {
  fill: color-mix(in srgb, var(--color-aubergine) 70%, var(--color-paper));
}

.sa-ring__wedge {
  fill: var(--color-satsuma);
  transform-box: view-box;
  transform-origin: 50px 50px;
}

.sa-ring__core {
  fill: var(--color-paper);
}

.sa-pack[data-popular="true"] .sa-ring__core {
  fill: var(--color-aubergine);
}

.sa-pack__name {
  display: flex;
  align-items: baseline;
  gap: 12px;
  font: 700 2rem / 1 var(--font-sa-display);
  letter-spacing: -0.03em;
}

.sa-pack__count {
  font: 500 0.9375rem/1 var(--font-sa-body);
  letter-spacing: 0;
  opacity: 0.72;
}

.sa-pack__price {
  display: grid;
  gap: 2px;
}

.sa-pack__amount {
  font: 800 3rem / 1 var(--font-sa-display);
  letter-spacing: -0.04em;
}

.sa-pack__per {
  font-size: 0.9375rem;
  opacity: 0.75;
}

.sa-pack__perks {
  display: grid;
  gap: 8px;
  margin-block: 10px 16px;
  padding-top: 16px;
  border-top: 1.5px dashed color-mix(in srgb, currentColor 28%, transparent);
}

.sa-pack__perks li {
  position: relative;
  padding-left: 24px;
}

.sa-pack__perks li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.45em;
  width: 11px;
  height: 11px;
  border-radius: 50% 50% 50% 0;
  background: var(--color-satsuma);
  rotate: -45deg;
}

.sa-pack__magnet {
  margin-top: auto;
  justify-self: start;
}

@media (hover: hover) and (pointer: fine) {
  .sa-pack:hover {
    transform: translateY(-6px);
  }
  .sa-packs__grid:has(.sa-pack:hover) .sa-pack:not(:hover) {
    opacity: 0.7;
  }
}

.sa-pack {
  transition:
    transform var(--dur-base) var(--ease-out),
    opacity var(--dur-base) var(--ease-out);
}

/* Brief form */
.sa-brief {
  background: var(--color-aubergine);
  color: var(--color-paper);
}

.sa-brief .sa-h2,
.sa-brief .sa-eyebrow,
.sa-brief .sa-eyebrow__n {
  color: var(--color-paper);
}

.sa-brief .sa-h2 em {
  background: linear-gradient(transparent 62%, var(--color-satsuma) 62% 92%, transparent 92%);
}

.sa-brief .sa-lede {
  color: color-mix(in srgb, var(--color-paper) 78%, var(--color-aubergine));
}

.sa-brief__grid {
  display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(0, 6fr);
  gap: clamp(32px, 6vw, 96px);
  align-items: start;
}

.sa-brief__facts {
  display: grid;
  gap: 14px;
  margin-top: 36px;
}

.sa-brief__facts li {
  display: flex;
  align-items: baseline;
  gap: 14px;
  padding-top: 14px;
  border-top: 1.5px dashed color-mix(in srgb, var(--color-paper) 28%, transparent);
  color: color-mix(in srgb, var(--color-paper) 78%, var(--color-aubergine));
}

.sa-brief__facts strong {
  min-width: 4.4ch;
  font: 800 1.9rem / 1 var(--font-sa-display);
  letter-spacing: -0.03em;
  color: var(--color-apricot);
}

.sa-brief__card {
  display: grid;
  border-radius: 32px;
  background: var(--color-paper);
  color: var(--color-ink);
  padding: clamp(22px, 3vw, 36px);
  overflow: hidden;
}

.sa-brief__card > * {
  grid-area: 1 / 1;
}

.sa-form {
  display: grid;
  gap: 14px;
  align-content: start;
  transition:
    opacity var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
}

.sa-field {
  position: relative;
}

.sa-input {
  width: 100%;
  min-height: 58px;
  padding: 24px 16px 8px;
  border: 0;
  border-radius: 16px;
  background: var(--sa-tint);
  box-shadow: inset 0 0 0 1.5px transparent;
  font-size: 1rem;
  line-height: 1.3;
  outline: 2px solid transparent;
  outline-offset: 2px;
  transition:
    box-shadow var(--dur-fast) var(--ease-out),
    outline-color var(--dur-fast) var(--ease-out),
    outline-offset var(--dur-base) var(--ease-out);
}

textarea.sa-input {
  resize: vertical;
  min-height: 96px;
}

select.sa-input {
  appearance: none;
  padding-right: 40px;
  background-image: linear-gradient(45deg, transparent 50%, currentColor 50%), linear-gradient(135deg, currentColor 50%, transparent 50%);
  background-position: calc(100% - 22px) 50%, calc(100% - 17px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.sa-input:focus-visible {
  outline-color: var(--color-aubergine);
  outline-offset: 0;
}

.sa-field label {
  position: absolute;
  left: 16px;
  top: 18px;
  color: var(--sa-muted);
  font-size: 1rem;
  line-height: 1;
  pointer-events: none;
  transform-origin: left top;
  transition:
    transform var(--dur-base) var(--ease-out),
    color var(--dur-fast) var(--ease-out);
}

.sa-input:focus ~ label,
.sa-field:not(.sa-field--select) .sa-input:not(:placeholder-shown) ~ label,
.sa-field[data-filled="true"] label {
  transform: translateY(-9px) scale(0.76);
  color: var(--color-aubergine);
}

.sa-field[data-invalid="true"] .sa-input {
  box-shadow: inset 0 0 0 2px var(--color-satsuma);
}

.sa-field__error {
  margin-top: 6px;
  padding-left: 4px;
  font-size: 0.875rem;
  font-weight: 500;
  color: color-mix(in srgb, var(--color-satsuma) 55%, var(--color-ink));
  animation: sa-slide-down var(--dur-base) var(--ease-out) both;
}

.sa-field__count {
  position: absolute;
  right: 14px;
  bottom: 10px;
  font-size: 0.75rem;
  color: var(--sa-muted);
  font-variant-numeric: tabular-nums;
}

.sa-packpick legend {
  margin-bottom: 8px;
  padding: 0;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--sa-muted);
}

.sa-packpick__row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.sa-packpick__opt {
  position: relative;
  cursor: pointer;
}

.sa-packpick__opt input {
  position: absolute;
  inset: 0;
  opacity: 0;
  margin: 0;
  cursor: pointer;
}

.sa-packpick__face {
  display: grid;
  gap: 2px;
  padding: 12px 14px;
  border-radius: 16px;
  background: var(--sa-tint);
  box-shadow: inset 0 0 0 1.5px transparent;
  transition:
    background-color var(--dur-fast) var(--ease-out),
    box-shadow var(--dur-fast) var(--ease-out),
    transform var(--dur-instant) var(--ease-out);
}

.sa-packpick__name {
  font: 700 1.05rem / 1.1 var(--font-sa-display);
}

.sa-packpick__meta {
  font-size: 0.78rem;
  color: var(--sa-muted);
}

.sa-packpick__opt input:checked + .sa-packpick__face {
  background: var(--color-apricot);
  box-shadow: inset 0 0 0 2px var(--color-aubergine);
}

.sa-packpick__opt input:focus-visible + .sa-packpick__face {
  outline: 2px solid var(--color-aubergine);
  outline-offset: 2px;
}

.sa-packpick__opt:active .sa-packpick__face {
  transform: scale(0.97);
}

.sa-form__submit {
  height: 56px;
  margin-top: 6px;
  font-size: 1.0625rem;
}

.sa-form__submit-label,
.sa-form__submit-busy {
  transition:
    opacity var(--dur-fast) var(--ease-out),
    transform var(--dur-base) var(--ease-out);
}

.sa-form__submit-busy {
  position: absolute;
  display: flex;
  gap: 6px;
  opacity: 0;
  transform: translateY(10px);
}

.sa-form__submit-busy i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: currentColor;
}

.sa-form__submit[data-loading="true"] .sa-form__submit-label {
  opacity: 0;
  transform: translateY(-10px);
}

.sa-form__submit[data-loading="true"] .sa-form__submit-busy {
  opacity: 1;
  transform: none;
}

.sa-form__fine {
  text-align: center;
  font-size: 0.875rem;
  color: var(--sa-muted);
}

.sa-brief__card[data-phase="success"] .sa-form {
  opacity: 0;
  transform: translateY(-16px) scale(0.98);
  pointer-events: none;
}

.sa-done {
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 12px;
  text-align: center;
  padding-block: 12px;
  opacity: 0;
  clip-path: inset(0 0 100% 0);
  visibility: hidden;
  transition:
    clip-path var(--dur-slow) var(--ease-in-out),
    opacity var(--dur-base) var(--ease-out),
    visibility 0s linear var(--dur-slow);
}

.sa-done:focus-visible {
  outline: none;
}

.sa-brief__card[data-phase="success"] .sa-done {
  opacity: 1;
  clip-path: inset(0);
  visibility: visible;
  transition-delay: 120ms, 120ms, 0s;
}

.sa-done__ring {
  width: 150px;
  height: 150px;
}

.sa-done__ref {
  padding: 6px 14px;
  border-radius: 999px;
  background: var(--color-apricot);
  font: 600 0.8125rem/1 var(--font-sa-body);
  letter-spacing: 0.1em;
  color: var(--color-aubergine);
}

.sa-done__title {
  font: 800 clamp(2rem, 4vw, 2.8rem) / 1 var(--font-sa-display);
  letter-spacing: -0.035em;
}

.sa-done__body {
  max-width: 38ch;
  color: var(--sa-muted);
}

.sa-done .sa-btn {
  margin-top: 8px;
}

/* Footer */
.sa-footer {
  background: var(--color-ink);
  color: var(--color-paper);
  padding-block: clamp(56px, 8vw, 100px) 28px;
}

.sa-footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 40px;
}

.sa-footer .sa-logo {
  color: var(--color-paper);
}

.sa-footer__tag {
  max-width: 36ch;
  margin-top: 18px;
  color: color-mix(in srgb, var(--color-paper) 72%, var(--color-ink));
}

.sa-footer__mail {
  display: inline-block;
  margin-top: 14px;
  color: var(--color-apricot);
}

.sa-footer__title {
  margin-bottom: 14px;
  font: 500 0.8125rem/1 var(--font-sa-body);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--color-paper) 62%, var(--color-ink));
}

.sa-footer ul {
  display: grid;
  gap: 10px;
}

.sa-footer a {
  text-decoration: none;
  background: linear-gradient(currentColor, currentColor) left bottom / 0% 1.5px no-repeat;
  transition: background-size var(--dur-base) var(--ease-out);
}

.sa-footer a:hover {
  background-size: 100% 1.5px;
}

.sa-footer__fine {
  margin-top: clamp(40px, 6vw, 80px);
  padding-top: 20px;
  border-top: 1px solid color-mix(in srgb, var(--color-paper) 16%, transparent);
  font-size: 0.875rem;
  color: color-mix(in srgb, var(--color-paper) 62%, var(--color-ink));
}

/* Image placeholder until an asset is generated */
.sa-placeholder {
  display: grid;
  place-items: center;
  background: repeating-linear-gradient(45deg, var(--color-apricot) 0 12px, color-mix(in srgb, var(--color-apricot) 70%, var(--color-paper)) 12px 24px);
  color: var(--color-aubergine);
  font: 500 0.8125rem/1 var(--font-sa-body);
}

/* ─────────────── Phones ─────────────── */
@media (max-width: 820px) {
  .sa-body {
    font-size: 1rem;
  }
  .sa-hero {
    height: auto;
    padding-top: 88px;
    padding-bottom: 36px;
  }
  html[data-sa-motion="live"] .sa-hero {
    position: relative;
  }
  .sa-hero__frame {
    width: 100%;
    height: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 18px;
    transform: none;
    opacity: 1;
  }
  .sa-h1,
  .sa-sub,
  .sa-cta,
  .sa-trust {
    position: relative;
    inset: auto;
    left: auto;
    top: auto;
    translate: none;
  }
  .sa-h1 {
    padding-inline: 20px;
    font-size: clamp(38px, 11vw, 56px);
    line-height: 1.04;
  }
  .sa-sub {
    width: auto;
    padding-inline: 24px;
    font-size: 16px;
    line-height: 1.55;
  }
  .sa-sub span {
    display: inline;
  }
  .sa-seal,
  .sa-sprig {
    display: none;
  }
  .sa-wheel {
    --wu: calc(100vw / 640);
    position: relative;
    left: auto;
    margin-left: 0;
    width: 100%;
    height: 250px;
    margin-block: 6px;
  }
  .sa-cta {
    width: 190px;
    height: 74px;
  }
  .sa-cta__magnet {
    translate: -6px -6px;
  }
  .sa-btn--hero {
    width: 172px;
    height: 58px;
    font-size: 17px;
  }
  .sa-trust {
    margin: -6px 0 0;
    padding-inline: 20px;
    font-size: 14px;
    white-space: normal;
    text-align: center;
  }
  .sa-steps,
  .sa-makers__grid,
  .sa-packs__grid {
    grid-template-columns: 1fr;
  }
  .sa-step__link {
    display: none;
  }
  .sa-brief__grid {
    grid-template-columns: 1fr;
  }
  .sa-packpick__row {
    grid-template-columns: 1fr;
  }
  .sa-footer__grid {
    grid-template-columns: 1fr 1fr;
  }
  .sa-footer__brand {
    grid-column: 1 / -1;
  }
}

@media (min-width: 821px) and (max-width: 1040px) {
  .sa-makers__grid,
  .sa-packs__grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .sa-steps {
    grid-template-columns: 1fr;
  }
  .sa-step__link {
    display: none;
  }
}

/* ─────────────── Keyframes ─────────────── */
@keyframes sa-load {
  from {
    opacity: 0;
    transform: translateY(calc(16 * var(--u)));
    filter: blur(8px);
  }
  to {
    opacity: 1;
    transform: none;
    filter: none;
  }
}

@keyframes sa-line {
  from {
    opacity: 0;
    transform: translateY(108%);
    filter: blur(10px);
  }
  to {
    opacity: 1;
    transform: none;
    filter: none;
  }
}

@keyframes sa-pop {
  from {
    opacity: 0;
    transform: scale(0.7);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes sa-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes sa-drop {
  from {
    opacity: 0;
    transform: translateY(-16px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes sa-wheel-rise {
  from {
    opacity: 0;
    transform: translateY(calc(90 * var(--u)));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes sa-draw {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes sa-slide-down {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes sa-shake-a {
  20%,
  60% {
    transform: translateX(-6px);
  }
  40%,
  80% {
    transform: translateX(6px);
  }
}

@keyframes sa-shake-b {
  20%,
  60% {
    transform: translateX(-6px);
  }
  40%,
  80% {
    transform: translateX(6px);
  }
}

@keyframes sa-marquee {
  to {
    transform: translateX(-50%);
  }
}

@keyframes sa-ring-pulse {
  50% {
    scale: 1.04;
  }
}

@keyframes sa-busy {
  0%,
  80%,
  100% {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-5px);
  }
}

@keyframes sa-wedge-fill {
  from {
    fill: var(--color-apricot);
    transform: scale(0.82);
  }
  to {
    fill: var(--color-satsuma);
    transform: none;
  }
}

/* Scene loops */
@keyframes sa-bob {
  50% {
    transform: translateY(-12px);
  }
}
@keyframes sa-tilt {
  0%,
  100% {
    transform: rotate(-5deg);
  }
  50% {
    transform: rotate(3deg);
  }
}
@keyframes sa-shadow {
  50% {
    transform: scaleX(0.86);
  }
}
@keyframes sa-splash {
  0% {
    opacity: 0;
    transform: translateY(40px) scale(0.3);
  }
  35% {
    opacity: 1;
  }
  100% {
    opacity: 0;
    transform: translateY(-34px) scale(1.5);
  }
}
@keyframes sa-ripple {
  0% {
    opacity: 0.9;
    transform: scale(0.25);
  }
  100% {
    opacity: 0;
    transform: scale(1.1);
  }
}
@keyframes sa-art {
  0%,
  35% {
    transform: scale(0);
  }
  60%,
  90% {
    transform: scale(1.2);
  }
  100% {
    transform: scale(0);
  }
}
@keyframes sa-pour {
  0% {
    transform: scaleY(0);
    transform-origin: 50% 0;
  }
  35%,
  60% {
    transform: scaleY(1);
    transform-origin: 50% 0;
  }
  80%,
  100% {
    transform: scaleY(0);
    transform-origin: 50% 100%;
  }
}
@keyframes sa-ring {
  0% {
    opacity: 0.9;
    transform: scale(0.7);
  }
  100% {
    opacity: 0;
    transform: scale(1.7);
  }
}
@keyframes sa-sway {
  0%,
  100% {
    transform: rotate(-4deg);
  }
  50% {
    transform: rotate(4deg);
  }
}
@keyframes sa-spin {
  0%,
  100% {
    transform: scaleX(0.7);
  }
  50% {
    transform: scaleX(1);
  }
}
@keyframes sa-drip {
  0% {
    opacity: 1;
    transform: translateY(-20px) scaleY(1.2);
  }
  55% {
    opacity: 1;
    transform: translateY(190px) scaleY(1);
  }
  60%,
  100% {
    opacity: 0;
    transform: translateY(210px) scale(0.2);
  }
}
@keyframes sa-swirl {
  to {
    transform: rotate(360deg);
  }
}
@keyframes sa-glow {
  50% {
    opacity: 0.55;
    transform: scale(1.08);
  }
}

/* ─────────────── Motion: only with motion allowed ─────────────── */
@media (prefers-reduced-motion: no-preference) {
  /* Hero load choreography: runs from CSS alone, so it plays before hydration and never shifts layout. */
  .sa-load {
    animation: sa-load var(--dur-hero) var(--ease-out-expo) var(--ld, 0ms) both;
  }
  .sa-h1__text.sa-load {
    animation: sa-line 1100ms var(--ease-out-expo) var(--ld, 0ms) both;
  }
  .sa-cta.sa-load {
    animation: sa-pop 800ms var(--ease-spring) var(--ld, 0ms) both;
  }
  .sa-sprig.sa-load,
  .sa-trust.sa-load {
    animation: sa-fade 600ms var(--ease-out) var(--ld, 0ms) both;
  }
  .sa-seal.sa-load {
    animation: sa-pop 900ms var(--ease-spring) var(--ld, 0ms) both;
  }
  .sa-seal__ring {
    animation: sa-turn 30s linear infinite;
  }
  .sa-sprig__leaf {
    animation: sa-unfurl 700ms var(--ease-spring) calc(var(--ld, 0ms) + 650ms + var(--n, 0) * 170ms) backwards;
  }
  .sa-hero[data-ambient="paused"] .sa-seal__ring {
    animation-play-state: paused;
  }
  .sa-draw {
    stroke-dashoffset: 1;
    animation: sa-draw 900ms var(--ease-out) calc(var(--ld, 0ms) + var(--n, 0) * 520ms) forwards;
  }
  /* The logo is the first thing painted and never animates: it is the page's LCP candidate. */
  .sa-nav li,
  .sa-header__login,
  .sa-header__signup,
  .sa-menu-toggle {
    animation: sa-drop 700ms var(--ease-out) calc(150ms + var(--i, 0) * 55ms) backwards;
  }
  .sa-header__login {
    --i: 5;
  }
  .sa-header__signup {
    --i: 6;
  }

  /* The wheel assembles from a flat row into its arc (JS); the row itself rises into place. */
  html[data-sa-motion="live"] .sa-wheel[data-ready="false"] {
    opacity: 0;
  }
  .sa-wheel[data-ready="true"] .sa-wheel__track {
    animation: sa-wheel-rise 1100ms var(--ease-out-expo) 100ms both;
  }

  .sa-cta__magnet {
    transition: translate var(--dur-base) var(--ease-spring);
  }

  .sa-marquee__track {
    animation: sa-marquee 42s linear infinite;
  }
  .sa-marquee[data-playing="false"] .sa-marquee__track,
  .sa-marquee:hover .sa-marquee__track,
  .sa-marquee:focus-within .sa-marquee__track {
    animation-play-state: paused;
  }

  .sa-form[data-shake="0"] .sa-field[data-invalid="true"] {
    animation: sa-shake-a 280ms var(--ease-out);
  }
  .sa-form[data-shake="1"] .sa-field[data-invalid="true"] {
    animation: sa-shake-b 280ms var(--ease-out);
  }
  .sa-form__submit[data-loading="true"] .sa-form__submit-busy i {
    animation: sa-busy 900ms var(--ease-out) infinite;
  }
  .sa-form__submit-busy i:nth-child(2) {
    animation-delay: 120ms;
  }
  .sa-form__submit-busy i:nth-child(3) {
    animation-delay: 240ms;
  }
  .sa-brief__card[data-phase="success"] .sa-done .sa-ring__wedge {

    animation: sa-wedge-fill 520ms var(--ease-spring) calc(260ms + var(--i, 0) * 70ms) both;
  }

  /* Scenes */
  .sa-a {
    animation-duration: 5s;
    animation-iteration-count: infinite;
    animation-timing-function: ease-in-out;
    animation-delay: var(--d, 0s);
  }
  .sa-a-bob { animation-name: sa-bob; }
  .sa-a-tilt { animation-name: sa-tilt; animation-duration: 4s; }
  .sa-a-shadow { animation-name: sa-shadow; animation-duration: 4s; }
  .sa-a-splash { animation-name: sa-splash; animation-duration: 2.8s; animation-timing-function: ease-out; }
  .sa-a-ripple { animation-name: sa-ripple; animation-duration: 2.4s; animation-timing-function: ease-out; }
  .sa-a-art { animation-name: sa-art; }
  .sa-a-pour { animation-name: sa-pour; }
  .sa-a-ring { animation-name: sa-ring; animation-duration: 2.7s; animation-timing-function: ease-out; }
  .sa-a-sway { animation-name: sa-sway; animation-duration: 3.6s; }
  .sa-a-spin { animation-name: sa-spin; animation-duration: 2s; }
  .sa-a-drop { animation-name: sa-drip; animation-duration: 3s; animation-timing-function: ease-in; }
  .sa-a-swirl { animation-name: sa-swirl; animation-duration: 12s; animation-timing-function: linear; }
  .sa-a-glow { animation-name: sa-glow; animation-duration: 4s; }

  /* Reveals: hidden only while motion is live, so no-JS and reduced-motion visitors get the finished page. */
  html[data-sa-motion="live"] [data-reveal] {
    --rv: var(--dur-slow) var(--ease-out);
  }

  html[data-sa-motion="live"] [data-reveal="mask"] .sa-mask > span {
    display: block;
    transition: transform 1000ms var(--ease-out-expo);
  }
  html[data-sa-motion="live"] [data-reveal="mask"] .sa-mask:nth-child(2) > span {
    transition-delay: 110ms;
  }
  html[data-sa-motion="live"] [data-reveal="mask"]:not([data-in="true"]) .sa-mask > span {
    transform: translateY(112%);
  }

  html[data-sa-motion="live"] [data-reveal="rise"] {
    transition:
      opacity var(--dur-slow) var(--ease-out),
      transform var(--dur-slow) var(--ease-out);
  }
  html[data-sa-motion="live"] [data-reveal="rise"]:not([data-in="true"]) {
    opacity: 0;
    transform: translateY(var(--reveal-shift));
  }

  html[data-sa-motion="live"] [data-reveal="scale"] {
    transition:
      opacity var(--dur-slow) var(--ease-out),
      transform var(--dur-slow) var(--ease-out-expo);
  }
  html[data-sa-motion="live"] [data-reveal="scale"]:not([data-in="true"]) {
    opacity: 0;
    transform: translateY(24px) scale(0.95);
  }

  html[data-sa-motion="live"] [data-reveal="cascade"] > * {
    transition:
      opacity var(--dur-slow) var(--ease-out),
      transform var(--dur-slow) var(--ease-out);
    transition-delay: calc(var(--i, 0) * var(--stagger));
  }
  html[data-sa-motion="live"] [data-reveal="cascade"]:not([data-in="true"]) > * {
    opacity: 0;
    transform: translateY(34px) scale(0.96);
  }

  html[data-sa-motion="live"] [data-reveal="draw"] .sa-eyebrow__rule,
  html[data-sa-motion="live"] .sa-eyebrow[data-reveal="draw"] .sa-eyebrow__rule {
    transition: transform var(--dur-slow) var(--ease-out-expo);
  }
  html[data-sa-motion="live"] [data-reveal="draw"]:not([data-in="true"]) .sa-eyebrow__rule {
    transform: scaleX(0);
  }

  /* Image wipes key off the revealed ancestor: an element clipped to nothing is never "in view" to an observer. */
  html[data-sa-motion="live"] .sa-maker__media {
    transition: clip-path 1000ms var(--ease-in-out) calc(160ms + var(--i, 0) * var(--stagger));
  }
  html[data-sa-motion="live"] [data-reveal]:not([data-in="true"]) .sa-maker__media {
    clip-path: inset(0 0 100% 0);
  }
  html[data-sa-motion="live"] [data-reveal]:not([data-in="true"]) .sa-maker__media > svg {
    scale: 1.14;
  }

  /* Scroll-drawn connectors and segment cascades. Descendant selectors, so they follow any revealed ancestor. */
  html[data-sa-motion="live"] .sa-draw--scroll {
    animation: none;
    stroke-dashoffset: 0;
    transition: stroke-dashoffset 1100ms var(--ease-out) 500ms;
  }
  html[data-sa-motion="live"] [data-reveal]:not([data-in="true"]) .sa-draw--scroll {
    stroke-dashoffset: 1;
  }
  html[data-sa-motion="live"] .sa-ring__wedge {
    transition:
      transform var(--dur-base) var(--ease-spring),
      opacity var(--dur-base) var(--ease-out);
    transition-delay: calc(300ms + var(--i, 0) * 38ms);
  }
  html[data-sa-motion="live"] [data-reveal]:not([data-in="true"]) .sa-ring__wedge {
    transform: scale(0.35);
    opacity: 0;
  }
  html[data-sa-motion="live"] .sa-done .sa-ring__wedge {
    transition: none;
  }
}

@keyframes sa-turn {
  to {
    transform: rotate(360deg);
  }
}

@keyframes sa-unfurl {
  from {
    opacity: 0;
    transform: scale(0.2) rotate(-12deg);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

